def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    counts = {}
    for row in g:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    divider = next(r for r, row in enumerate(g)
                   if len(set(row)) == 1 and row[0] != bg)

    # Find the non-background object on either side of the divider.
    above = [(r, c) for r in range(divider) for c in range(w)
             if g[r][c] != bg]
    below = [(r, c) for r in range(divider + 1, h) for c in range(w)
             if g[r][c] != bg]
    cells = above if above else below
    if not cells:
        return g

    rows = [r for r, c in cells]
    top, bottom = min(rows), max(rows)
    old = [row[:] for row in g]

    if above:
        shift = divider - 1 - bottom
        for r, c in cells:
            g[r][c] = bg
        for r, c in cells:
            g[r + shift][c] = old[r][c]
        mark = top + shift - 1
    else:
        shift = divider + 1 - top
        for r, c in cells:
            g[r][c] = bg
        for r, c in cells:
            g[r + shift][c] = old[r][c]
        mark = bottom + shift + 1

    if 0 <= mark < h:
        g[mark] = [8] * w
    return g
